import * as THREE from 'three';
// 1. scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x101820);
// 2. camera
const camera = new THREE.PerspectiveCamera(
75, // field of view (deg)
window.innerWidth / window.innerHeight, // aspect
0.1, // near plane
1000 // far plane
);
camera.position.set(2, 2, 4);
camera.lookAt(0, 0, 0);
// 3. renderer
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);
// 4. mesh
const cube = new THREE.Mesh(
new THREE.BoxGeometry(1, 1, 1),
new THREE.MeshStandardMaterial({ color: 0x66ccff, roughness: 0.4 })
);
scene.add(cube);
// lights (MeshStandardMaterial needs them)
scene.add(new THREE.AmbientLight(0xffffff, 0.4));
const sun = new THREE.DirectionalLight(0xffffff, 1.0);
sun.position.set(5, 10, 7);
scene.add(sun);
// 5. animation loop
renderer.setAnimationLoop(() => {
cube.rotation.x += 0.01;
cube.rotation.y += 0.012;
renderer.render(scene, camera);
});
// handle resize
window.addEventListener('resize', () => {
camera.aspect = window.innerWidth / window.innerHeight;
camera.updateProjectionMatrix();
renderer.setSize(window.innerWidth, window.innerHeight);
});
That is the canonical "hello, world" of Three.js. The remaining 13 posts deepen each part.

import * as THREE from 'three';
import WebGPU from 'three/addons/capabilities/WebGPU.js';
import WebGL from 'three/addons/capabilities/WebGL.js';
let renderer;
if (await WebGPU.IsAvailableAsync()) {
const { WebGPURenderer } = await import('three/webgpu');
renderer = new WebGPURenderer({ antialias: true });
await renderer.init();
} else if (WebGL.isWebGL2Available()) {
renderer = new THREE.WebGLRenderer({ antialias: true });
} else {
document.body.append(WebGL.getWebGL2ErrorMessage());
throw new Error('no GPU available');
}

